class Storage:
    def __init__(self):
        self.fenced_epoch = 0
        self.data = {}

    def write(self, epoch, key, value):
        # Fencing: only the holder of the latest epoch may write.
        # Old primary with stale epoch is rejected loudly, not merged silently.
        if epoch < self.fenced_epoch:
            raise StalePrimaryError(f"reject epoch {epoch}, fenced at {self.fenced_epoch}")
        if epoch > self.fenced_epoch:
            self.fenced_epoch = epoch
        self.data[key] = (value, epoch)
        return True

# On partition heal, writes from epoch 12 fail loudly once epoch 13 fenced.
# Loud rejection is the point: it turns split brain into unavailability.
